"""Public tests for the 2025 midterm, Problem 1 (skyline).
Passing them does not establish correctness or complexity."""
import copy
import random
import unittest
import skyline as q

RECTS1 = [(1, 11, 5), (2, 6, 7), (3, 13, 9), (12, 7, 16),
          (14, 3, 25), (19, 18, 22), (23, 13, 29), (24, 4, 28)]
SKY1 = [(1, 11), (3, 13), (9, 0), (12, 7), (16, 3), (19, 18), (22, 3), (23, 13), (29, 0)]
SKY1_RED = [(1, 11), (2, 11), (3, 13), (5, 13), (7, 13), (9, 0), (12, 7), (14, 7), (16, 3),
            (19, 18), (22, 3), (23, 13), (24, 13), (25, 13), (28, 13), (29, 0)]
S3 = [(1, 11), (5, 6), (7, 0), (12, 7), (16, 0), (19, 18), (22, 0), (24, 4), (28, 0)]
S4 = [(3, 13), (9, 0), (14, 3), (23, 13), (29, 0)]
S5 = [(1, 10), (3, 5), (8, 0)]
S6 = [(1, 20), (3, 2), (10, 0)]
T = [(1, 20), (3, 5), (8, 2), (10, 0)]


def norm(S):
    return [tuple(s) for s in S]


def ref_height(L, x):
    return max([0] + [h for (l, h, r) in L if l <= x < r])


def ref_skyline(L):
    """Independent reference, straight from the definition."""
    xs = sorted({l for (l, _, _) in L} | {r for (_, _, r) in L})
    out, cur = [], 0
    for x in xs:
        h = ref_height(L, x)
        if h != cur:
            out.append((x, h))
            cur = h
    return out


def rand_rects(rng, n, span=30):
    out = []
    for _ in range(n):
        l = rng.randrange(0, span)
        out.append((l, rng.randrange(1, 15), l + rng.randrange(1, 10)))
    return out


class TestQ1(unittest.TestCase):
    def test_figure_values(self):
        expected = {0: 0, 1: 11, 2: 11, 3: 13, 5: 13, 7: 13, 9: 0, 10: 0, 12: 7,
                    22: 3, 24: 13, 28: 13, 29: 0, 40: 0}
        for x, h in expected.items():
            self.assertEqual(q.rects_height_at(RECTS1, x), h, "x=%d" % x)

    def test_edges(self):
        self.assertEqual(q.rects_height_at([], 3), 0)
        self.assertEqual(q.rects_height_at([(2, 5, 4)], 2), 5)   # left side included
        self.assertEqual(q.rects_height_at([(2, 5, 4)], 4), 0)   # right side excluded
        self.assertEqual(q.rects_height_at([(2, 5, 4), (3, 9, 6)], 3), 9)

    def test_input_untouched(self):
        L = copy.deepcopy(RECTS1)
        q.rects_height_at(L, 5)
        self.assertEqual(L, RECTS1)


class TestQ2(unittest.TestCase):
    def test_example(self):
        self.assertEqual(norm(q.simplify_skyline(SKY1_RED)), SKY1)

    def test_already_minimal(self):
        self.assertEqual(norm(q.simplify_skyline(SKY1)), SKY1)
        self.assertEqual(norm(q.simplify_skyline([(1, 5), (3, 0)])), [(1, 5), (3, 0)])

    def test_repeated_and_trailing(self):
        self.assertEqual(norm(q.simplify_skyline([(1, 5), (2, 5), (3, 5), (4, 0)])), [(1, 5), (4, 0)])
        self.assertEqual(norm(q.simplify_skyline([(1, 5), (3, 0), (4, 0)])), [(1, 5), (3, 0)])

    def test_input_untouched(self):
        S = list(SKY1_RED)
        q.simplify_skyline(S)
        self.assertEqual(S, SKY1_RED)


class TestQ3(unittest.TestCase):
    def test_figure(self):
        self.assertEqual(norm(q.skyline_naive(RECTS1)), SKY1)

    def test_special_cases(self):
        self.assertEqual(norm(q.skyline_naive([(2, 5, 4)])), [(2, 5), (4, 0)])
        self.assertEqual(norm(q.skyline_naive([(1, 5, 10), (2, 3, 4)])), [(1, 5), (10, 0)])    # hidden building
        self.assertEqual(norm(q.skyline_naive([(1, 5, 3), (3, 5, 6)])), [(1, 5), (6, 0)])      # touching, same height
        self.assertEqual(norm(q.skyline_naive([(1, 2, 3), (5, 4, 6)])), [(1, 2), (3, 0), (5, 4), (6, 0)])  # gap
        self.assertEqual(norm(q.skyline_naive([(1, 5, 3), (1, 5, 3)])), [(1, 5), (3, 0)])      # duplicate

    def test_random(self):
        rng = random.Random(202)
        for n in range(1, 25):
            L = rand_rects(rng, n)
            copy_of_L = list(L)
            self.assertEqual(norm(q.skyline_naive(L)), ref_skyline(L), L)
            self.assertEqual(L, copy_of_L)


class TestQ4(unittest.TestCase):
    def test_figures(self):
        self.assertEqual(norm(q.combine_skylines(S3, S4)), SKY1)
        self.assertEqual(norm(q.combine_skylines(S4, S3)), SKY1)
        self.assertEqual(norm(q.combine_skylines(S5, S6)), T)     # shared coordinates
        self.assertEqual(norm(q.combine_skylines(S6, S5)), T)

    def test_special_cases(self):
        self.assertEqual(norm(q.combine_skylines([(1, 2), (3, 0)], [(5, 4), (6, 0)])),
                         [(1, 2), (3, 0), (5, 4), (6, 0)])
        self.assertEqual(norm(q.combine_skylines([(1, 2), (3, 0)], [(3, 2), (5, 0)])), [(1, 2), (5, 0)])
        self.assertEqual(norm(q.combine_skylines(S3, S3)), S3)

    def test_inputs_untouched(self):
        a, b = list(S3), list(S4)
        q.combine_skylines(a, b)
        self.assertEqual((a, b), (S3, S4))

    def test_random(self):
        rng = random.Random(204)
        for _ in range(150):
            L1, L2 = rand_rects(rng, rng.randrange(1, 8)), rand_rects(rng, rng.randrange(1, 8))
            got = q.combine_skylines(ref_skyline(L1), ref_skyline(L2))
            self.assertEqual(norm(got), ref_skyline(L1 + L2), (L1, L2))


class TestQ5(unittest.TestCase):
    def test_figure(self):
        self.assertEqual(norm(q.skyline_dac(RECTS1)), SKY1)

    def test_small(self):
        self.assertEqual(norm(q.skyline_dac([(2, 5, 4)])), [(2, 5), (4, 0)])
        self.assertEqual(norm(q.skyline_dac([(1, 5, 3), (3, 5, 6)])), [(1, 5), (6, 0)])

    def test_random(self):
        rng = random.Random(205)
        for n in list(range(1, 30)) + [150]:
            L = rand_rects(rng, n, span=60)
            copy_of_L = list(L)
            self.assertEqual(norm(q.skyline_dac(L)), ref_skyline(L), L)
            self.assertEqual(L, copy_of_L)


if __name__ == '__main__':
    unittest.main(verbosity=2)
